css:
.fx-on .hero-inner {
  transform: translateY(var(--hero-shift, 0));
  opacity: var(--hero-fade, 1);
  will-change: transform, opacity;
}

.hero { min-height: 100vh; display: flex; align-items: center; padding: 0 60px; }
.hero-inner { max-width: 1360px; }
.hero-title { font-weight: 700; font-size: clamp(34px, 5.5vw, 56px); letter-spacing: -0.03em; line-height: 1.05; margin-bottom: 28px; }
.hero-desc { font-size: 16px; color: var(--text-muted); line-height: 1.6; }
.depois { min-height: 100vh; padding: 90px 60px; border-top: 1px solid var(--border); background: var(--bg-alt); }
.demo-heading { font-weight: 600; font-size: clamp(26px, 3.5vw, 40px); letter-spacing: -0.03em; }

js:
// O conteúdo do hero sobe um pouco e desbota conforme a página rola — o
// suficiente para dar profundidade contra as linhas do fundo, que ficam
// paradas. Para de calcular assim que o hero sai da tela.
export function initHeroScroll() {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

  const hero = document.getElementById('heroInner');
  if (!hero) return;

  document.documentElement.classList.add('fx-on');

  let pendente = false;

  function pintar() {
    pendente = false;
    const altura = window.innerHeight;
    const avanco = Math.min(window.scrollY / altura, 1);
    hero.style.setProperty('--hero-shift', (avanco * -70).toFixed(1) + 'px');
    hero.style.setProperty('--hero-fade', (1 - avanco * 0.55).toFixed(3));
  }

  window.addEventListener('scroll', function () {
    if (window.scrollY > window.innerHeight * 1.2) return;
    if (!pendente) {
      pendente = true;
      requestAnimationFrame(pintar);
    }
  }, { passive: true });

  // Cobre a página abrindo já rolada (recarregar no meio, voltar do histórico).
  pintar();
}
